## Code Example
```javascript
function indexRepo(files) {
  // naive tokenization
  const index = {};
  for (const f of files) {
    const tokens = f.content.split(/\\W+/).filter(Boolean);
    tokens.forEach(t => (index[t] ||= []).push(f.path));
  }
  return index;
}
```

